ites',$property->suites) }}"></label><label>Banheiros<input type="number" name="bathrooms" value="{{ old('bathrooms',$property->bathrooms) }}"></label><label>Vagas<input type="number" name="parking_spaces" value="{{ old('parking_spaces',$property->parking_spaces) }}"></label><label class="wide">Descrição<textarea name="description" rows="8" required>{{ old('description',$property->description) }}</textarea></label><label class="wide">Fotos<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple></label><label class="check wide"><input type="hidden" name="featured" value="0"><input type="checkbox" name="featured" value="1" @checked(old('featured',$property->featured))> Destacar na página inicial</label><button class="primary">Salvar imóvel</button></form>@endsection
